  "usage.filter": { en:"Filter", es:"Filtrar", pt:"Filtrar", fr:"Filtrer", it:"Filtra", de:"Filter", zh:"筛选", ar:"تصفية", ru:"Фильтр", ms:"Tapis", hi:"फ़िल्टर" },
  "usage.endpointFilter.tip": { en:"Show only calls whose endpoint name contains this text. Filters the table and recomputes the KPIs and charts above.", es:"Mostrar solo las llamadas cuyo nombre de endpoint contiene este texto. Filtra la tabla y recalcula los KPI y los gráficos de arriba.", pt:"Mostrar apenas chamadas cujo nome de endpoint contém este texto. Filtra a tabela e recalcula os KPIs e gráficos acima.", fr:"Afficher uniquement les appels dont le nom du point de terminaison contient ce texte. Filtre le tableau et recalcule les KPI et graphiques ci-dessus.", it:"Mostra solo le chiamate il cui nome endpoint contiene questo testo. Filtra la tabella e ricalcola i KPI e i grafici sopra.", de:"Nur Aufrufe anzeigen, deren Endpoint-Name diesen Text enthält. Filtert die Tabelle und berechnet die KPIs und Diagramme oben neu.", zh:"仅显示端点名称包含此文本的调用。会筛选表格并重新计算上方的 KPI 和图表。", ar:"إظهار الاستدعاءات التي يحتوي اسم نقطة النهاية فيها على هذا النص فقط. يصفّي الجدول ويعيد حساب مؤشرات الأداء والرسوم البيانية أعلاه.", ru:"Показывать только вызовы, имя эндпоинта которых содержит этот текст. Фильтрует таблицу и пересчитывает KPI и графики выше.", ms:"Tunjukkan hanya panggilan yang nama endpointnya mengandungi teks ini. Menapis jadual dan mengira semula KPI serta carta di atas.", hi:"केवल वे कॉल दिखाएँ जिनके endpoint नाम में यह पाठ हो। तालिका को फ़िल्टर करता है और ऊपर के KPI और चार्ट पुनः गणना करता है।" },
  "usage.conversationFilter.tip": { en:"Show only calls whose conversation name contains this text. Filters the table and recomputes the KPIs and charts above.", es:"Mostrar solo las llamadas cuyo nombre de conversación contiene este texto. Filtra la tabla y recalcula los KPI y los gráficos de arriba.", pt:"Mostrar apenas chamadas cujo nome de conversa contém este texto. Filtra a tabela e recalcula os KPIs e gráficos acima.", fr:"Afficher uniquement les appels dont le nom de la conversation contient ce texte. Filtre le tableau et recalcule les KPI et graphiques ci-dessus.", it:"Mostra solo le chiamate il cui nome conversazione contiene questo testo. Filtra la tabella e ricalcola i KPI e i grafici sopra.", de:"Nur Aufrufe anzeigen, deren Unterhaltungsname diesen Text enthält. Filtert die Tabelle und berechnet die KPIs und Diagramme oben neu.", zh:"仅显示对话名称包含此文本的调用。会筛选表格并重新计算上方的 KPI 和图表。", ar:"إظهار الاستدعاءات التي يحتوي اسم المحادثة فيها على هذا النص فقط. يصفّي الجدول ويعيد حساب مؤشرات الأداء والرسوم البيانية أعلاه.", ru:"Показывать только вызовы, имя разговора которых содержит этот текст. Фильтрует таблицу и пересчитывает KPI и графики выше.", ms:"Tunjukkan hanya panggilan yang nama perbualannya mengandungi teks ini. Menapis jadual dan mengira semula KPI serta carta di atas.", hi:"केवल वे कॉल दिखाएँ जिनके बातचीत नाम में यह पाठ हो। तालिका को फ़िल्टर करता है और ऊपर के KPI और चार्ट पुनः गणना करता है।" },
