  "usage.metric.ttft.tip": { en:"Chart time-to-first-token distribution per time bucket.", es:"Gráfico de la distribución del tiempo hasta el primer token por intervalo de tiempo.", pt:"Gráfico da distribuição do tempo até o primeiro token por intervalo de tempo.", fr:"Représente la distribution du temps jusqu'au premier jeton par intervalle de temps.", it:"Grafico della distribuzione del tempo al primo token per intervallo temporale.", de:"Diagramm der Verteilung der Zeit bis zum ersten Token pro Zeitintervall.", zh:"按时间段绘制首个令牌时间分布图表。", ar:"رسم توزيع زمن الوصول إلى أول رمز لكل فترة زمنية.", ru:"График распределения времени до первого токена по каждому интервалу времени.", ms:"Carta taburan masa-ke-token-pertama setiap baldi masa.", hi:"प्रति समय-बकेट टाइम-टू-फ़र्स्ट-टोकन वितरण का चार्ट।" },
  "usage.metric.streaming.tip": { en:"Chart streaming (generation) time distribution per time bucket.", es:"Gráfico de la distribución del tiempo de streaming (generación) por intervalo de tiempo.", pt:"Gráfico da distribuição do tempo de streaming (geração) por intervalo de tempo.", fr:"Représente la distribution du temps de streaming (génération) par intervalle de temps.", it:"Grafico della distribuzione del tempo di streaming (generazione) per intervallo temporale.", de:"Diagramm der Verteilung der Streaming-Zeit (Generierung) pro Zeitintervall.", zh:"按时间段绘制流式（生成）时间分布图表。", ar:"رسم توزيع زمن البث (التوليد) لكل فترة زمنية.", ru:"График распределения времени потоковой передачи (генерации) по каждому интервалу времени.", ms:"Carta taburan masa penstriman (penjanaan) setiap baldi masa.", hi:"प्रति समय-बकेट स्ट्रीमिंग (उत्पादन) समय वितरण का चार्ट।" },
