  "reasoning.off.tip": { en:"Send no reasoning field.", es:"No enviar ningún campo de razonamiento.", pt:"Não enviar nenhum campo de raciocínio.", fr:"N'envoyer aucun champ de raisonnement.", it:"Non inviare alcun campo di ragionamento.", de:"Kein Reasoning-Feld senden.", zh:"不发送推理字段。", ar:"عدم إرسال أي حقل استدلال.", ru:"Не отправлять поле рассуждений.", ms:"Jangan hantar medan penaakulan.", hi:"कोई तर्क फ़ील्ड न भेजें।" },
  "reasoning.minimal.tip": { en:"The lightest reasoning.", es:"El razonamiento más ligero.", pt:"O raciocínio mais leve.", fr:"Le raisonnement le plus léger.", it:"Il ragionamento più leggero.", de:"Das leichteste Reasoning.", zh:"最轻量的推理。", ar:"أخف استدلال.", ru:"Самое лёгкое рассуждение.", ms:"Penaakulan paling ringan.", hi:"सबसे हल्का तर्क।" },
  "reasoning.low.tip": { en:"A little reasoning.", es:"Un poco de razonamiento.", pt:"Um pouco de raciocínio.", fr:"Un peu de raisonnement.", it:"Un po' di ragionamento.", de:"Ein wenig Reasoning.", zh:"少量推理。", ar:"استدلال قليل.", ru:"Немного рассуждений.", ms:"Penaakulan sedikit.", hi:"थोड़ा तर्क।" },
  "reasoning.medium.tip": { en:"Balanced reasoning.", es:"Razonamiento equilibrado.", pt:"Raciocínio equilibrado.", fr:"Raisonnement équilibré.", it:"Ragionamento bilanciato.", de:"Ausgewogenes Reasoning.", zh:"均衡的推理。", ar:"استدلال متوازن.", ru:"Сбалансированное рассуждение.", ms:"Penaakulan seimbang.", hi:"संतुलित तर्क।" },
  "reasoning.high.tip": { en:"The most reasoning.", es:"El máximo de razonamiento.", pt:"O máximo de raciocínio.", fr:"Le maximum de raisonnement.", it:"Il massimo ragionamento.", de:"Das meiste Reasoning.", zh:"最充分的推理。", ar:"أقصى استدلال.", ru:"Максимум рассуждений.", ms:"Penaakulan paling banyak.", hi:"सर्वाधिक तर्क।" },
  "reasoning.cancel.tip": { en:"Close without changing the reasoning effort.", es:"Cerrar sin cambiar el esfuerzo de razonamiento.", pt:"Fechar sem alterar o esforço de raciocínio.", fr:"Fermer sans changer l'effort de raisonnement.", it:"Chiudi senza modificare lo sforzo di ragionamento.", de:"Schließen, ohne den Reasoning-Aufwand zu ändern.", zh:"关闭且不更改推理强度。", ar:"الإغلاق دون تغيير جهد الاستدلال.", ru:"Закрыть, не меняя усилие на рассуждения.", ms:"Tutup tanpa menukar usaha penaakulan.", hi:"तर्क प्रयास बदले बिना बंद करें।" },
  "palette.search.placeholder": { en:"Type a command…", es:"Escribe un comando…", pt:"Digite um comando…", fr:"Tapez une commande…", it:"Digita un comando…", de:"Einen Befehl eingeben…", zh:"输入命令…", ar:"اكتب أمرًا…", ru:"Введите команду…", ms:"Taip perintah…", hi:"कोई कमांड टाइप करें…" },
  "palette.title": { en:"Commands", es:"Comandos", pt:"Comandos", fr:"Commandes", it:"Comandi", de:"Befehle", zh:"命令", ar:"الأوامر", ru:"Команды", ms:"Perintah", hi:"कमांड" },
  "localServer.title": { en:"Local server", es:"Servidor local", pt:"Servidor local", fr:"Serveur local", it:"Server locale", de:"Lokaler Server", zh:"本地服务器", ar:"الخادم المحلي", ru:"Локальный сервер", ms:"Pelayan tempatan", hi:"स्थानीय सर्वर" },
  "localServer.description": { en:"Optionally run the mux REST API and web dashboard in-process, bound to loopback. This is off by default — the app always works without it. Turn it on to reach mux from a browser or another tool on this machine.", es:"Opcionalmente ejecuta la API REST de mux y el panel web en el proceso, enlazados a loopback. Está desactivado de forma predeterminada: la app siempre funciona sin ello. Actívalo para acceder a mux desde un navegador u otra herramienta en esta máquina.", pt:"Opcionalmente, execute a API REST do mux e o painel web em processo, vinculados ao loopback. Isso fica desativado por padrão — o app sempre funciona sem isso. Ative para acessar o mux a partir de um navegador ou de outra ferramenta nesta máquina.", fr:"Exécutez éventuellement l'API REST mux et le tableau de bord web en interne, liés à la boucle locale. Ceci est désactivé par défaut — l'application fonctionne toujours sans. Activez-le pour joindre mux depuis un navigateur ou un autre outil sur cette machine.", it:"Esegui facoltativamente l'API REST di mux e la dashboard web in-process, associate al loopback. È disattivato per impostazione predefinita — l'app funziona sempre anche senza. Attivalo per raggiungere mux da un browser o da un altro strumento su questa macchina.", de:"Führe optional die mux REST API und das Web-Dashboard im selben Prozess aus, gebunden an Loopback. Dies ist standardmäßig aus – die App funktioniert immer auch ohne. Schalte es ein, um mux von einem Browser oder einem anderen Tool auf diesem Rechner zu erreichen.", zh:"可选择在进程内运行 mux REST API 和网页仪表盘，绑定到回环地址。此项默认关闭——应用无需它也始终可用。开启后可从浏览器或本机上的其他工具访问 mux。", ar:"شغّل اختياريًا واجهة mux REST API ولوحة الويب داخل العملية، مرتبطة بالاسترجاع المحلي (loopback). هذا معطّل افتراضيًا — يعمل التطبيق دائمًا بدونه. فعّله للوصول إلى mux من متصفّح أو أداة أخرى على هذا الجهاز.", ru:"При желании запустите REST API mux и веб-панель в том же процессе, привязанные к loopback. По умолчанию это отключено — приложение всегда работает и без этого. Включите, чтобы обращаться к mux из браузера или другого инструмента на этой машине.", ms:"Secara pilihan jalankan API REST mux dan papan pemuka web dalam-proses, terikat kepada gelung balik. Ini mati secara lalai — apl sentiasa berfungsi tanpanya. Hidupkannya untuk mencapai mux dari pelayar atau alat lain pada mesin ini.", hi:"वैकल्पिक रूप से mux REST API और वेब डैशबोर्ड को इन-प्रोसेस चलाएँ, जो loopback से बंधा हो। यह डिफ़ॉल्ट रूप से बंद है — ऐप इसके बिना भी हमेशा काम करता है। इस मशीन पर किसी ब्राउज़र या अन्य टूल से mux तक पहुँचने के लिए इसे चालू करें।" },
