  "endpoint.badge.default": { en:"default", es:"predeterminado", pt:"padrão", fr:"par défaut", it:"predefinito", de:"Standard", zh:"默认", ar:"افتراضي", ru:"по умолчанию", ms:"lalai", hi:"डिफ़ॉल्ट" },
  "endpoint.col.name.tip": { en:"The endpoint's display name. The green “default” badge marks the endpoint new conversations use.", es:"El nombre visible del endpoint. La insignia verde «predeterminado» marca el endpoint que usan las conversaciones nuevas.", pt:"O nome de exibição do endpoint. A etiqueta verde “padrão” marca o endpoint que as novas conversas usam.", fr:"Le nom affiché du point de terminaison. Le badge vert « par défaut » indique le point de terminaison utilisé par les nouvelles conversations.", it:"Il nome visualizzato dell'endpoint. Il badge verde “predefinito” indica l'endpoint usato dalle nuove conversazioni.", de:"Der Anzeigename des Endpoints. Das grüne „Standard“-Abzeichen markiert den Endpoint, den neue Unterhaltungen verwenden.", zh:"端点的显示名称。绿色的“默认”徽章标记新对话所使用的端点。", ar:"الاسم المعروض لنقطة النهاية. تحدد شارة “افتراضي” الخضراء نقطة النهاية التي تستخدمها المحادثات الجديدة.", ru:"Отображаемое имя эндпоинта. Зелёный значок «по умолчанию» отмечает эндпоинт, который используют новые разговоры.", ms:"Nama paparan endpoint. Lencana hijau “lalai” menandakan endpoint yang digunakan oleh perbualan baharu.", hi:"endpoint का प्रदर्शन नाम। हरा “डिफ़ॉल्ट” बैज उस endpoint को चिह्नित करता है जिसका उपयोग नई बातचीतें करती हैं।" },
  "endpoint.col.adapter": { en:"Adapter", es:"Adaptador", pt:"Adaptador", fr:"Adaptateur", it:"Adattatore", de:"Adapter", zh:"适配器", ar:"المحوّل", ru:"Адаптер", ms:"Penyesuai", hi:"एडाप्टर" },
  "endpoint.col.adapter.tip": { en:"The provider protocol this endpoint speaks (OpenAI, Ollama, Anthropic, and so on).", es:"El protocolo de proveedor que habla este endpoint (OpenAI, Ollama, Anthropic, etc.).", pt:"O protocolo de provedor que este endpoint fala (OpenAI, Ollama, Anthropic e assim por diante).", fr:"Le protocole du fournisseur que parle ce point de terminaison (OpenAI, Ollama, Anthropic, etc.).", it:"Il protocollo del provider parlato da questo endpoint (OpenAI, Ollama, Anthropic e così via).", de:"Das Provider-Protokoll, das dieser Endpoint spricht (OpenAI, Ollama, Anthropic usw.).", zh:"此端点使用的提供方协议（OpenAI、Ollama、Anthropic 等）。", ar:"بروتوكول المزوّد الذي تتحدّث به نقطة النهاية هذه (OpenAI، Ollama، Anthropic، وما إلى ذلك).", ru:"Протокол провайдера, на котором говорит этот эндпоинт (OpenAI, Ollama, Anthropic и так далее).", ms:"Protokol pembekal yang dituturkan oleh endpoint ini (OpenAI, Ollama, Anthropic, dan sebagainya).", hi:"वह प्रदाता प्रोटोकॉल जिसे यह endpoint बोलता है (OpenAI, Ollama, Anthropic, इत्यादि)।" },
