  "endpointVal.probing": { en:"Sending a probe request to the endpoint…", es:"Enviando una solicitud de sondeo al endpoint…", pt:"Enviando uma solicitação de teste ao endpoint…", fr:"Envoi d'une requête de sonde au point de terminaison…", it:"Invio di una richiesta di prova all'endpoint…", de:"Sende eine Testanfrage an den Endpoint…", zh:"正在向端点发送探测请求…", ar:"إرسال طلب فحص إلى نقطة النهاية…", ru:"Отправка пробного запроса на эндпоинт…", ms:"Menghantar permintaan penyiasat ke endpoint…", hi:"endpoint को एक जाँच अनुरोध भेजा जा रहा है…" },
  "endpointVal.probingStream": { en:"Sending a streaming probe and waiting for the first token…", es:"Enviando un sondeo en streaming y esperando el primer token…", pt:"Enviando um teste de streaming e aguardando o primeiro token…", fr:"Envoi d'une sonde en streaming et attente du premier jeton…", it:"Invio di una prova in streaming e attesa del primo token…", de:"Sende eine Streaming-Testanfrage und warte auf das erste Token…", zh:"正在发送流式探测并等待首个令牌…", ar:"إرسال فحص بثّي والانتظار حتى أول رمز…", ru:"Отправка потокового пробного запроса и ожидание первого токена…", ms:"Menghantar penyiasat penstriman dan menunggu token pertama…", hi:"एक स्ट्रीमिंग जाँच भेजी जा रही है और पहले टोकन की प्रतीक्षा की जा रही है…" },
  "endpointVal.revalidate": { en:"Re-validate", es:"Revalidar", pt:"Revalidar", fr:"Revalider", it:"Riconvalida", de:"Erneut validieren", zh:"重新验证", ar:"إعادة التحقق", ru:"Проверить снова", ms:"Sahkan semula", hi:"पुनः सत्यापित करें" },
