  "mcp.col.status.tip": { en:"Connectivity, probed when this window opens: green ✓ = reachable, red ✗ = failed, … = checking.", es:"Conectividad, sondeada al abrir esta ventana: verde ✓ = accesible, rojo ✗ = falló, … = comprobando.", pt:"Conectividade, testada quando esta janela é aberta: verde ✓ = acessível, vermelho ✗ = falhou, … = verificando.", fr:"Connectivité, sondée à l'ouverture de cette fenêtre : vert ✓ = accessible, rouge ✗ = échec, … = vérification.", it:"Connettività, sondata all'apertura di questa finestra: verde ✓ = raggiungibile, rosso ✗ = fallita, … = verifica in corso.", de:"Konnektivität, geprüft beim Öffnen dieses Fensters: grün ✓ = erreichbar, rot ✗ = fehlgeschlagen, … = wird geprüft.", zh:"连接状态，在此窗口打开时探测：绿色 ✓ = 可访问，红色 ✗ = 失败，… = 检查中。", ar:"الاتصال، يُفحص عند فتح هذه النافذة: أخضر ✓ = يمكن الوصول، أحمر ✗ = فشل، … = جارٍ الفحص.", ru:"Подключаемость, проверяется при открытии этого окна: зелёный ✓ = доступен, красный ✗ = не удалось, … = проверка.", ms:"Kesambungan, disiasat apabila tetingkap ini dibuka: hijau ✓ = boleh dicapai, merah ✗ = gagal, … = memeriksa.", hi:"कनेक्टिविटी, जो यह विंडो खुलने पर जाँची जाती है: हरा ✓ = पहुँच योग्य, लाल ✗ = विफल, … = जाँच रहा है।" },
  "mcp.col.name.tip": { en:"The MCP server's unique name, used to reference its tools.", es:"El nombre único del servidor MCP, usado para referenciar sus herramientas.", pt:"O nome único do servidor MCP, usado para referenciar suas ferramentas.", fr:"Le nom unique du serveur MCP, utilisé pour référencer ses outils.", it:"Il nome univoco del server MCP, usato per riferirsi ai suoi strumenti.", de:"Der eindeutige Name des MCP-Servers, mit dem auf seine Tools verwiesen wird.", zh:"MCP 服务器的唯一名称，用于引用其工具。", ar:"الاسم الفريد لخادم MCP، يُستخدم للإشارة إلى أدواته.", ru:"Уникальное имя MCP-сервера, используемое для ссылки на его инструменты.", ms:"Nama unik pelayan MCP, digunakan untuk merujuk alatnya.", hi:"MCP सर्वर का अद्वितीय नाम, जिसका उपयोग उसके टूल संदर्भित करने के लिए होता है।" },
  "mcp.transport": { en:"Transport", es:"Transporte", pt:"Transporte", fr:"Transport", it:"Trasporto", de:"Transport", zh:"传输方式", ar:"النقل", ru:"Транспорт", ms:"Pengangkutan", hi:"ट्रांसपोर्ट" },
  "mcp.col.transport.tip": { en:"How mux connects: stdio launches a local process; http connects to a URL.", es:"Cómo se conecta mux: stdio lanza un proceso local; http se conecta a una URL.", pt:"Como o mux se conecta: stdio inicia um processo local; http conecta a uma URL.", fr:"Comment mux se connecte : stdio lance un processus local ; http se connecte à une URL.", it:"Come si connette mux: stdio avvia un processo locale; http si connette a un URL.", de:"Wie mux sich verbindet: stdio startet einen lokalen Prozess; http verbindet sich mit einer URL.", zh:"mux 的连接方式：stdio 启动本地进程；http 连接到 URL。", ar:"كيفية اتصال mux: يشغّل stdio عملية محلية؛ ويتصل http بعنوان URL.", ru:"Как mux подключается: stdio запускает локальный процесс; http подключается к URL.", ms:"Bagaimana mux menyambung: stdio melancarkan proses tempatan; http menyambung ke URL.", hi:"mux कैसे जुड़ता है: stdio एक स्थानीय प्रोसेस लॉन्च करता है; http एक URL से जुड़ता है।" },
  "mcp.target": { en:"Target", es:"Destino", pt:"Destino", fr:"Cible", it:"Destinazione", de:"Ziel", zh:"目标", ar:"الهدف", ru:"Цель", ms:"Sasaran", hi:"लक्ष्य" },
