  "mcp.auth": { en:"Auth", es:"Autenticación", pt:"Autenticação", fr:"Authentification", it:"Autenticazione", de:"Auth", zh:"认证", ar:"المصادقة", ru:"Аутентификация", ms:"Pengesahan", hi:"प्रमाणन" },
  "mcp.col.auth.tip": { en:"The authentication scheme sent with HTTP requests (none, bearer token, or API key header).", es:"El esquema de autenticación enviado con las solicitudes HTTP (ninguno, token bearer o encabezado de clave de API).", pt:"O esquema de autenticação enviado com solicitações HTTP (nenhum, token bearer ou cabeçalho de chave de API).", fr:"Le schéma d'authentification envoyé avec les requêtes HTTP (aucun, jeton bearer ou en-tête de clé API).", it:"Lo schema di autenticazione inviato con le richieste HTTP (nessuno, token bearer o header con chiave API).", de:"Das Authentifizierungsschema, das mit HTTP-Anfragen gesendet wird (kein, Bearer-Token oder API-Schlüssel-Header).", zh:"随 HTTP 请求发送的认证方案（无、Bearer 令牌或 API 密钥头）。", ar:"مخطط المصادقة المُرسل مع طلبات HTTP (بدون، رمز bearer، أو ترويسة مفتاح API).", ru:"Схема аутентификации, отправляемая с HTTP-запросами (нет, токен bearer или заголовок с ключом API).", ms:"Skema pengesahan yang dihantar dengan permintaan HTTP (tiada, token bearer, atau pengepala kunci API).", hi:"HTTP अनुरोधों के साथ भेजी गई प्रमाणीकरण योजना (कोई नहीं, bearer टोकन, या API कुंजी हेडर)।" },
