  "search.providerType.tip": { en:"Which search backend this is. Only wired-up types (tavily, you) will actually run.", es:"Qué backend de búsqueda es este. Solo se ejecutarán realmente los tipos ya integrados (tavily, you).", pt:"Qual backend de busca é este. Apenas os tipos integrados (tavily, you) realmente funcionarão.", fr:"De quel backend de recherche il s'agit. Seuls les types raccordés (tavily, you) s'exécuteront réellement.", it:"Quale backend di ricerca è questo. Solo i tipi collegati (tavily, you) verranno effettivamente eseguiti.", de:"Welches Suche-Backend dies ist. Nur angebundene Typen (tavily, you) werden tatsächlich ausgeführt.", zh:"这是哪种搜索后端。只有已接入的类型（tavily、you）才会实际运行。", ar:"أي خلفية بحث هذه. الأنواع المدعومة فقط (tavily، you) هي التي ستعمل فعليًا.", ru:"Какой это бэкенд поиска. Реально работают только подключённые типы (tavily, you).", ms:"Bahagian belakang carian yang manakah ini. Hanya jenis yang telah disambungkan (tavily, you) akan benar-benar berjalan.", hi:"यह कौन सा खोज बैकएंड है। केवल जुड़े हुए प्रकार (tavily, you) ही वास्तव में चलेंगे।" },
  "search.endpoint.tip": { en:"The provider's API base URL (leave blank to use the provider's default).", es:"La URL base de la API del proveedor (déjala en blanco para usar el predeterminado del proveedor).", pt:"A URL base da API do provedor (deixe em branco para usar o padrão do provedor).", fr:"L'URL de base de l'API du fournisseur (laissez vide pour utiliser la valeur par défaut du fournisseur).", it:"L'URL di base dell'API del provider (lascia vuoto per usare il predefinito del provider).", de:"Die API-Basis-URL des Anbieters (leer lassen, um den Standard des Anbieters zu verwenden).", zh:"提供方的 API 基础 URL（留空则使用提供方的默认值）。", ar:"عنوان URL الأساسي لواجهة API الخاصة بالمزوّد (اتركه فارغًا لاستخدام افتراضي المزوّد).", ru:"Базовый URL API провайдера (оставьте пустым, чтобы использовать значение провайдера по умолчанию).", ms:"URL asas API pembekal (biarkan kosong untuk menggunakan lalai pembekal).", hi:"प्रदाता का API base URL (प्रदाता का डिफ़ॉल्ट उपयोग करने के लिए खाली छोड़ें)।" },
  "search.apiKey": { en:"API key", es:"Clave de API", pt:"Chave de API", fr:"Clé API", it:"Chiave API", de:"API-Schlüssel", zh:"API 密钥", ar:"مفتاح API", ru:"Ключ API", ms:"Kunci API", hi:"API कुंजी" },
  "search.apiKey.tip": { en:"Your API key for the provider, or an env-var reference the provider resolves.", es:"Tu clave de API para el proveedor, o una referencia a variable de entorno que el proveedor resuelve.", pt:"Sua chave de API para o provedor, ou uma referência de variável de ambiente que o provedor resolve.", fr:"Votre clé API pour le fournisseur, ou une référence à une variable d'environnement que le fournisseur résout.", it:"La tua chiave API per il provider, o un riferimento a variabile d'ambiente che il provider risolve.", de:"Dein API-Schlüssel für den Anbieter oder ein Env-Var-Verweis, den der Anbieter auflöst.", zh:"你用于该提供方的 API 密钥，或由提供方解析的环境变量引用。", ar:"مفتاح API الخاص بك للمزوّد، أو إشارة إلى متغير بيئة يحلّها المزوّد.", ru:"Ваш ключ API для провайдера или ссылка на переменную окружения, которую провайдер разрешает.", ms:"Kunci API anda untuk pembekal, atau rujukan pemboleh ubah persekitaran yang diselesaikan oleh pembekal.", hi:"प्रदाता के लिए आपकी API कुंजी, या एक env-var संदर्भ जिसे प्रदाता हल करता है।" },
  "search.timeout": { en:"Timeout (ms)", es:"Tiempo de espera (ms)", pt:"Tempo limite (ms)", fr:"Délai d'expiration (ms)", it:"Timeout (ms)", de:"Timeout (ms)", zh:"超时 (ms)", ar:"المهلة (ms)", ru:"Таймаут (мс)", ms:"Had masa (ms)", hi:"टाइमआउट (ms)" },
