  "search.enabled.tip": { en:"Include this provider when the agent performs a web search.", es:"Incluir este proveedor cuando el agente realice una búsqueda web.", pt:"Incluir este provedor quando o agente realizar uma busca na web.", fr:"Inclure ce fournisseur lorsque l'agent effectue une recherche web.", it:"Includi questo provider quando l'agente esegue una ricerca web.", de:"Diesen Anbieter einbeziehen, wenn der Agent eine Websuche durchführt.", zh:"当代理执行网页搜索时包含此提供方。", ar:"تضمين هذا المزوّد عندما يجري الوكيل بحثًا على الويب.", ru:"Включать этого провайдера, когда агент выполняет веб-поиск.", ms:"Sertakan pembekal ini apabila ejen melakukan carian web.", hi:"जब एजेंट वेब खोज करे तो इस प्रदाता को शामिल करें।" },
  "search.useDefault.tip": { en:"Try this provider first before any others.", es:"Probar este proveedor antes que los demás.", pt:"Tentar este provedor antes de qualquer outro.", fr:"Essayer ce fournisseur en premier avant tous les autres.", it:"Prova questo provider prima di ogni altro.", de:"Diesen Anbieter vor allen anderen zuerst versuchen.", zh:"在其他提供方之前先尝试此提供方。", ar:"جرّب هذا المزوّد أولًا قبل أي مزوّد آخر.", ru:"Пробовать этого провайдера первым, прежде чем остальных.", ms:"Cuba pembekal ini dahulu sebelum yang lain.", hi:"किसी और से पहले इस प्रदाता को आज़माएँ।" },
  "search.cancel.tip": { en:"Discard changes and close.", es:"Descartar los cambios y cerrar.", pt:"Descartar alterações e fechar.", fr:"Annuler les modifications et fermer.", it:"Annulla le modifiche e chiudi.", de:"Änderungen verwerfen und schließen.", zh:"放弃更改并关闭。", ar:"تجاهل التغييرات والإغلاق.", ru:"Отменить изменения и закрыть.", ms:"Buang perubahan dan tutup.", hi:"बदलाव रद्द करें और बंद करें।" },
  "search.save.tip": { en:"Save this search provider.", es:"Guardar este proveedor de búsqueda.", pt:"Salvar este provedor de busca.", fr:"Enregistrer ce fournisseur de recherche.", it:"Salva questo provider di ricerca.", de:"Diesen Suchanbieter speichern.", zh:"保存此搜索提供方。", ar:"حفظ مزوّد البحث هذا.", ru:"Сохранить этого провайдера поиска.", ms:"Simpan pembekal carian ini.", hi:"इस खोज प्रदाता को सहेजें।" },
  "search.err.nameRequired": { en:"Name is required.", es:"El nombre es obligatorio.", pt:"O nome é obrigatório.", fr:"Le nom est requis.", it:"Il nome è obbligatorio.", de:"Name ist erforderlich.", zh:"名称为必填项。", ar:"الاسم مطلوب.", ru:"Имя обязательно.", ms:"Nama diperlukan.", hi:"नाम आवश्यक है।" },
  "search.err.timeout": { en:"Timeout must be a whole number of at least 1000 ms.", es:"El tiempo de espera debe ser un número entero de al menos 1000 ms.", pt:"O tempo limite deve ser um número inteiro de pelo menos 1000 ms.", fr:"Le délai d'expiration doit être un nombre entier d'au moins 1000 ms.", it:"Il timeout deve essere un numero intero di almeno 1000 ms.", de:"Der Timeout muss eine ganze Zahl von mindestens 1000 ms sein.", zh:"超时必须是不小于 1000 ms 的整数。", ar:"يجب أن تكون المهلة عددًا صحيحًا لا يقل عن 1000 ms.", ru:"Таймаут должен быть целым числом не менее 1000 мс.", ms:"Had masa mesti nombor bulat sekurang-kurangnya 1000 ms.", hi:"टाइमआउट कम से कम 1000 ms की पूर्ण संख्या होनी चाहिए।" },
