  "skill.add": { en:"Add skill", es:"Añadir skill", pt:"Adicionar skill", fr:"Ajouter une compétence", it:"Aggiungi skill", de:"Skill hinzufügen", zh:"添加技能", ar:"إضافة مهارة", ru:"Добавить навык", ms:"Tambah kemahiran", hi:"skill जोड़ें" },
